             <fieldset>
               <legend>How do you prefer to receive notifications?</legend>
               <div class="options" role="radiogroup" aria-label="Notification delivery method">
                 <div class="option">
                   <input type="radio" id="email" name="notification" value="Email" required />
                   <label for="email">Email</label>
